<script lang="ts">
 import {onMount} from 'svelte';
 import ProjectTicketPage from './ProjectTicketPage.svelte';
 let {view='overview'}:{view?:string}=$props();
 import {page} from '$app/state';
 import {goto,beforeNavigate} from '$app/navigation';
 import {localization} from '$lib/localization';
 import {historyTitle,historyLines} from '$lib/project-history';
 import {readSessionUser} from '$lib/client-session';
 import {canOperate,type SessionUser} from '$lib/auth';
 import {canProject,personName,projectRequest,projectError,type Project,type Ticket,type TicketDetail,type Person,type Relation,type History} from '$lib/projects';
 import AssetManagementShell from '$lib/components/AssetManagementShell.svelte';
 import MasterPageHeader from '$lib/components/MasterPageHeader.svelte';
 import ActionButton from '$lib/components/ActionButton.svelte';
 import DeleteIconButton from '$lib/components/DeleteIconButton.svelte';
 import AddButton from '$lib/components/AddButton.svelte';
 import FormInput from '$lib/components/FormInput.svelte';
 import SearchSelect from '$lib/components/SearchSelect.svelte';
 import StatusNotice from '$lib/components/StatusNotice.svelte';
 import ProjectForm from './ProjectForm.svelte';
 import TicketModal from './TicketModal.svelte';
 import ProjectSettings from './ProjectSettings.svelte';
 let project=$state<Project|null>(null),user=$state<SessionUser|null>(null),tickets=$state<Ticket[]>([]),relations=$state<Relation[]>([]),loading=$state(true),busy=$state(false),error=$state(''),notice=$state(''),tab=$derived(view),editProject=$state(false),archivedNoticeHidden=$state(false),selected=$state<TicketDetail|null>(null),ticketOpen=$state(false),parentId=$state<number|null>(null),trigger=$state<HTMLElement|null>(null),settingsDirty=$state(false),history=$state<History[]>([]),historyTotal=$state(0),people=$state<Person[]>([]),directorySearch=$state(''),directoryTotal=$state(0),memberId=$state(''),memberRole=$state('editor'),engagements=$state<Array<{id:number;name:string}>>([]);
 let ja=$derived($localization.displayLanguage==='ja');const tr=(j:string,e:string)=>ja?j:e;
 let ticketPage=$state<ProjectTicketPage>();
 const root=()=>'/v1/projects/'+page.params.id;
 let tabs=$derived([{id:'overview',label:tr('概要','Overview')},{id:'tickets',label:tr('チケット','Tickets')},{id:'board',label:tr('かんばん','Board')},{id:'gantt',label:tr('ガント','Gantt')},{id:'history',label:tr('履歴','History')},{id:'members',label:tr('参加者','Members')},...(project&&canProject(project,'settings.manage',true)?[{id:'settings',label:tr('設定','Settings')}]:[])]);
 $effect(()=>{if(tab==='history'&&project)void loadHistory();});
 beforeNavigate(n=>{if(settingsDirty&&!confirm(tr('設定変更を破棄しますか？','Discard settings changes?')))n.cancel();});
 async function load(){project=await projectRequest<Project>(root());}
 async function loadTickets(more=false){const offset=more?tickets.length:0;const r=await fetch(root()+`/tickets?limit=500&offset=${offset}&sortBy=position&sortOrder=asc`);const payload=await r.json();if(!r.ok)throw new Error(payload.error?.code);tickets=more?[...tickets,...payload.data]:payload.data;relations=payload.meta.relations;}
 async function directory(more=false){try{const offset=more?people.length:0;const r=await fetch('/v1/projects/directory?limit=100&offset='+offset+'&search='+encodeURIComponent(directorySearch));const payload=await r.json();if(!r.ok)throw new Error();people=more?[...people,...payload.data]:payload.data;directoryTotal=payload.meta.total;}catch(e){error=projectError(e,ja);}}
 async function loadHistory(more=false){try{const r=await fetch(root()+`/history?limit=100&offset=${more?history.length:0}&sortOrder=desc`),payload=await r.json();if(!r.ok)throw new Error();history=more?[...history,...payload.data]:payload.data;historyTotal=payload.meta.total;}catch(e){error=projectError(e,ja);}}
 async function openTicket(t:Ticket,el:HTMLElement|null=null){try{await loadTickets();selected=await projectRequest<TicketDetail>(root()+'/tickets/'+t.id);trigger=el;ticketOpen=true;parentId=null;const url=new URL(page.url);url.searchParams.set('ticket',selected.code);await goto(url.pathname+url.search,{replaceState:true,keepFocus:true,noScroll:true});}catch(e){error=projectError(e,ja);}}
 async function newTicket(parent:Ticket|null=null){try{await loadTickets();selected=null;parentId=parent?.id??null;ticketOpen=true;}catch(e){error=projectError(e,ja);}}
 async function closeTicket(){ticketOpen=false;selected=null;const url=new URL(page.url);url.searchParams.delete('ticket');await goto(url.pathname+url.search,{replaceState:true,keepFocus:true,noScroll:true});}
 async function changed(t:TicketDetail|null){if(t)selected=t;await load();await ticketPage?.refresh();if(tab==='history')await loadHistory();}
 async function member(employeeId:number,role:string){if(!project)return;busy=true;error='';try{project=await projectRequest<Project>(root()+'/members/'+employeeId,'PATCH',{revision:project.revision,role});notice=tr('参加者を更新しました。','Members updated.');}catch(e){error=projectError(e,ja);}finally{busy=false;}}
 async function remove(){if(!project||!confirm(tr('このプロジェクトに所属しているすべての情報が削除されます。本当に削除してよろしいですか？','All information belonging to this project will be deleted. Are you sure you want to delete it?')))return;busy=true;try{await projectRequest(root()+'?revision='+project.revision,'DELETE');await goto('/projects');}catch(e){error=projectError(e,ja);}finally{busy=false;}}
 onMount(()=>{void(async()=>{try{user=await readSessionUser();await load();if(canOperate(user,'projects.members.manage'))await directory();if(canOperate(user,'engagements.read')){let offset=0;while(true){const rows=await projectRequest<Array<{id:number;name:string}>>('/v1/engagements?limit=500&offset='+offset);engagements.push(...rows);if(rows.length<500)break;offset+=500;}}}catch(e){error=projectError(e,ja);}finally{loading=false;}})();});
</script>
<AssetManagementShell title={project?.name??tr('プロジェクト','Projects')}><div class="workspace"><MasterPageHeader title={project?.name??tr('プロジェクト','Projects')}/>
 <div class="toolbar"><ActionButton label={tr('プロジェクト一覧','All projects')} onclick={()=>void goto('/projects')}/>{#if project}<span>{project.code} · {project.name}</span><div class="toolbar-actions">{#if canProject(project,'update',true)}<ActionButton label={tr('プロジェクトを編集','Edit project')} disabled={settingsDirty||busy} onclick={()=>editProject=true}/>{/if}{#if project.status!=='archived'&&canProject(project,'tickets.create')}<AddButton iconOnly label={tr('チケットを追加','Add ticket')} disabled={settingsDirty||busy} onclick={e=>{trigger=e.currentTarget as HTMLElement;newTicket();}}/>{/if}</div>{/if}</div>
 {#if error}<StatusNotice message={error} tone="error" onDismiss={()=>error=''}/>{/if}{#if notice}<StatusNotice message={notice} tone="success" onDismiss={()=>notice=''}/>{/if}
 {#if loading}<p>{tr('読み込み中…','Loading…')}</p>{:else if project}
 {#if project.status==='archived'&&!archivedNoticeHidden}<StatusNotice tone="info" onDismiss={()=>archivedNoticeHidden=true} message={tr('このプロジェクトはアーカイブされています。','This project is archived.')}/>{/if}
 <nav class="project-nav" aria-label={tr('プロジェクト内の機能','Project navigation')}>{#each tabs as item}<a id={`project-${item.id}-tab`} href={'/projects/'+project.code+'/'+item.id} aria-current={tab===item.id?'page':undefined}>{item.label}</a>{/each}</nav>
 {#if ['tickets','board','gantt'].includes(tab)}<ProjectTicketPage bind:this={ticketPage} view={tab} projectId={project.id} embedded/>{:else}
 <div class="content-card" class:settings-panel={tab==='settings'} role="tabpanel" id={`project-${tab}-panel`} aria-labelledby={`project-${tab}-tab`}>
 {#if tab==='overview'}
 <div class="overview"><div><h2>{tr('進捗','Progress')}</h2><strong class="metric">{project.counts.filter(c=>project?.statuses.some(s=>s.id===c.statusId&&s.category==='done')).reduce((n,c)=>n+c._count,0)} / {project.counts.reduce((n,c)=>n+c._count,0)}</strong><p>{tr('完了チケット／全チケット','Completed / total tickets')}</p></div><div><h2>{tr('工数（分）','Time (minutes)')}</h2><strong class="metric">{project.actualMinutes} / {project.estimatedMinutes}</strong><p>{tr('実績／見積。各チケットの直接分を合計。','Actual / estimated. Sum of direct entries.')}</p></div></div>
 <dl><dt>{tr('公開範囲','Visibility')}</dt><dd>{project.visibility==='private'?tr('参加者限定','Members only'):tr('社内公開','Internal')}</dd><dt>{tr('状態','Status')}</dt><dd>{({active:tr('進行中','Active'),on_hold:tr('保留','On hold'),completed:tr('完了','Completed'),archived:tr('アーカイブ','Archived')} as Record<string,string>)[project.status]}</dd><dt>{tr('説明','Description')}</dt><dd class="text">{project.description||''}</dd>{#if project.engagement}<dt>{tr('関連する案件','Engagement')}</dt><dd><a href="/engagements">{project.engagement.code} · {project.engagement.name}</a></dd>{/if}</dl>
 {#if canProject(project,'delete',true)}<DeleteIconButton label={tr('プロジェクトを削除','Delete project')} disabled={busy} onclick={remove}/>{/if}
 {:else if tab==='members'}
 <div class="member-list">{#each project.members as m}<div class="member-row"><span>{personName(m.employee)}</span>{#if project.status!=='archived'&&canProject(project,'members.manage',true)}<SearchSelect label={tr('役割','Role')} field={'member-role-'+m.employeeId} value={m.role} options={['manager','editor','viewer'].map((v,i)=>({value:v,label:[tr('管理者','Manager'),tr('編集者','Editor'),tr('閲覧者','Viewer')][i]}))} searchable={false} disabled={busy} onSelect={v=>void member(m.employeeId,v)}/><DeleteIconButton label={tr('参加を解除','Remove member')} disabled={busy} onclick={()=>{if(confirm(tr('参加を解除しますか？','Remove this member?')))void member(m.employeeId,'removed');}}/>{:else}<span>{m.role==='manager'?tr('管理者','Manager'):m.role==='editor'?tr('編集者','Editor'):tr('閲覧者','Viewer')}</span>{/if}</div>{/each}</div>
 {#if project.status!=='archived'&&canProject(project,'members.manage',true)}<div class="member-add"><FormInput label={tr('社員を検索','Search employees')} field="directory-search" value={directorySearch} onValueChange={v=>directorySearch=v} onCommit={()=>void directory()}/><ActionButton label={tr('検索','Search')} disabled={busy} onclick={()=>void directory()}/><SearchSelect label={tr('追加する社員','Employee to add')} field="new-member" value={memberId} options={people.filter(p=>!project?.members.some(m=>m.employeeId===p.id)).map(p=>({value:String(p.id),label:personName(p)}))} onSelect={v=>memberId=v}/><SearchSelect label={tr('役割','Role')} field="new-member-role" value={memberRole} options={['manager','editor','viewer'].map((v,i)=>({value:v,label:[tr('管理者','Manager'),tr('編集者','Editor'),tr('閲覧者','Viewer')][i]}))} searchable={false} onSelect={v=>memberRole=v}/><ActionButton label={tr('参加者を追加','Add member')} variant="primary" disabled={busy||!memberId} onclick={()=>void member(Number(memberId),memberRole)}/>{#if people.length<directoryTotal}<ActionButton label={tr('候補をさらに読み込む','Load more employees')} onclick={()=>void directory(true)}/>{/if}</div>{/if}
 {:else if tab==='settings'&&canProject(project,'settings.manage',true)}<ProjectSettings {project} ondirty={v=>settingsDirty=v} onsaved={p=>{project=p;}}/>
 {:else if tab==='history'}
 {#each history as h}<article class="history-entry"><strong>{historyTitle(h.kind,ja)}</strong><small>{h.createdAt.slice(0,19).replace('T',' ')} · {personName(h.actor)}</small>{#if h.ticketId}<button class="history-ticket" onclick={()=>void openTicket({id:h.ticketId} as Ticket)}>{h.ticketCode??tr('削除済みチケット','Deleted ticket')}</button>{/if}<details><summary>{tr('変更内容','Changes')}</summary><ul>{#each historyLines(h.detail,project,ja) as line}<li class="text">{line}</li>{/each}</ul></details></article>{/each}{#if history.length<historyTotal}<ActionButton label={tr('さらに読み込む','Load more')} onclick={()=>void loadHistory(true)}/>{/if}
 {/if}
 </div>{/if}{/if}
</div></AssetManagementShell>
{#if project&&editProject}<ProjectForm {project} {engagements} onclose={()=>editProject=false} onsaved={p=>{project=p;editProject=false;notice=tr('保存しました。','Saved.');}}/>{/if}
{#if project&&user&&ticketOpen}<TicketModal {project} ticket={selected} {tickets} {relations} employeeId={user.id} {parentId} returnFocus={trigger} onclose={()=>void closeTicket()} onchanged={changed}/>{/if}
<style>
 .project-nav{display:flex;gap:12px;flex-wrap:wrap;background:var(--surface);border:1px solid var(--border);border-radius:6px;padding:0 16px}.project-nav a{padding:12px 8px;min-height:44px;color:var(--muted);font-size:var(--font-size-body);text-decoration:none;border-bottom:2px solid transparent}.project-nav a[aria-current='page']{color:var(--action-primary);border-color:var(--action-primary)}
 .settings-panel.content-card{padding:0;border:0;background:transparent;box-shadow:none}.workspace{display:grid;gap:16px;min-width:0;max-width:100%}.toolbar,.toolbar-actions{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.toolbar>span{font-size:var(--font-size-body);font-weight:500;overflow-wrap:anywhere}.toolbar-actions{margin-left:auto}.content-card{min-width:0;border:1px solid var(--border);background:var(--surface);border-radius:var(--sph-radius-8px);box-shadow:var(--shadow);padding:20px;display:grid;gap:16px}.overview{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.overview>div{padding:16px;background:var(--surface-hover);border-radius:var(--sph-radius-4px)}h2{font-size:var(--font-size-body);margin:0 0 12px}.metric{font-size:24px}p,small,dt{font-size:var(--font-size-support);color:var(--muted)}dl{display:grid;grid-template-columns:140px minmax(0,1fr);gap:12px}dd{margin:0;overflow-wrap:anywhere}.text{white-space:pre-wrap}.member-list{display:grid;gap:12px}.member-row{display:flex;align-items:center;gap:16px;flex-wrap:wrap;padding:12px;border-bottom:1px solid var(--border)}.member-row>span{flex:1;min-width:180px}.member-add{display:flex;gap:12px;align-items:end;flex-wrap:wrap}.member-add>:global(:first-child){min-width:200px}.history-entry{border-bottom:1px solid var(--border);padding:12px 0;display:grid;gap:8px}.history-ticket{background:none;border:0;color:var(--action-primary);text-align:left;cursor:pointer}@media(max-width:700px){.content-card{padding:12px}.overview{grid-template-columns:1fr}.toolbar-actions{margin-left:0}dl{grid-template-columns:1fr;gap:6px}.member-row{padding:8px 0;gap:8px}}
</style>

